#include <stdio.h>

int is_anagram(const char *a, const char *b) {
    int counts[26] = {0};
    for (int i = 0; a[i] != '\0'; i++) counts[a[i] - 'a']++;
    for (int i = 0; b[i] != '\0'; i++) counts[b[i] - 'a']--;
    for (int i = 0; i < 26; i++) {
        if (counts[i] != 0) return 0;
    }
    return 1;
}

int main() {
    printf("%d\n", is_anagram("triangle", "integral"));
    printf("%d\n", is_anagram("apple", "pale"));
    return 0;
}
